static int64_t g_port_onPrinterDiscovered = 0;

void HybridNitroPrinting::emit_onPrintJobChanged(void* item) {
    int64_t port = g_port_onPrintJobChanged;
    if (port == 0) { return; }
    Dart_CObject obj;
    obj.type = Dart_CObject_kInt64;
    obj.value.as_int64 = (intptr_t)item;
    if (!Dart_PostCObject_DL(port, &obj)) {
        g_port_onPrintJobChanged = 0;
        free(item);
        return;
    }
}

